8|\section{选择运算}
9|=
10|\begin{method}[选择哪种运算？]\label{met:g2:problems:choose}
11|\begin{enumerate}
12|  \item \emph{合在一起，共有多少}：用加法（$+$）；
13|  \item \emph{拿走一些，问还剩多少或相差多少}：用减
14|        法（$-$）；
15|  \item \emph{若干个相同的组}：用乘法（$\times$）；
16|  \item 不确定时，画一个简单的图，并且
17|        总用一句话作答。
18|\end{enumerate}
19|\end{method}
20|
21|\begin{omfigure}
22|\begin{tikzpicture}[scale=0.6]
23|  % put together
24|  \draw[thick, fill=omDef!20] (0,0) rectangle (3,0.8);
25|  \draw[thick, fill=omThm!20] (3,0) rectangle (4.6,0.8);
26|  \node[font=\small] at (1.5,0.4) {$24$};
27|  \node[font=\small] at (3.8,0.4) {$15$};
28|  \draw[Stealth-Stealth] (0,-0.4) -- (4.6,-0.4);
29|  \node[below, font=\small] at (2.3,-0.5) {共有多少：$24 + 15$};
30|  % compare
31|  \begin{scope}[xshift=8cm]
32|  \draw[thick, fill=omDef!20] (0,0.9) rectangle (4.6,1.7);
33|  \node[font=\small] at (2.3,1.3) {$40$};
34|  \draw[thick, fill=omThm!20] (0,0) rectangle (2.8,0.8);
35|  \node[font=\small] at (1.4,0.4) {$28$};
36|  \draw[Stealth-Stealth] (2.8,0.4) -- (4.6,0.4);
37|  \node[below, font=\small] at (2.3,-0.2) {相差多少：$40 - 28$};
38|  \end{scope}
39|\end{tikzpicture}
40|
41|{\small 条形图：两个条形相连表示加法，两个
42|条形相比较表示减法。}
43|\end{omfigure}
