80|\begin{example}[象形图]\label{ex:g2:problems:pictogram}
81|先看图例：这里一个苹果代表 $2$ 个水果。
82|
83|\begin{omfigure}
84|\begin{tikzpicture}[scale=0.62]
85|  \node[left, font=\small] at (0,2) {红色};
86|  \foreach \i in {0,1,2,3} \fill[omThm] (0.5+\i*0.75,2) circle (0.24);
87|  \node[left, font=\small] at (0,1) {绿色};
88|  \foreach \i in {0,1} \fill[omMeth] (0.5+\i*0.75,1) circle (0.24);
89|  \node[left, font=\small] at (0,0) {黄色};
90|  \foreach \i in {0,1,2} \fill[omProp] (0.5+\i*0.75,0) circle (0.24);
91|  \node[right, font=\small] at (4.0,1) {图例：一个圆点 $= 2$ 个水果};
92|\end{tikzpicture}
93|
94|{\small 象形图：红色有 $4$ 个圆点，所以红色
95|水果有 $4 \times 2 = 8$ 个；绿色 $2$ 个圆点，$4$ 个水果；黄色 $3$ 个圆点，$6$ 个水果。}
96|\end{omfigure}
97|\end{example}
